/**
 * Ingest Analytics Events
 *
 * Record a batch of product-analytics events.
 *
 * Authentication is optional, and that is the point: the events worth the
 * most are the ones from people who do not have an account yet — a guide
 * reader clicking through to a diagnostic. Those land with user_id null
 * rather than being turned away.
 *
 * Two things are never taken from the request body:
 *
 * user_id comes from the bearer token. A client that could name its own
 * user_id could attribute its behaviour to any account it liked, which would
 * make the table worse than not having one.
 *
 * attempt_id is accepted but verified. An event naming an attempt the caller
 * did not sit is rejected outright rather than stored with the attempt_id
 * stripped: silently downgrading it would leave a real bug (a client sending
 * the wrong id) looking like ordinary anonymous traffic. A legitimate client
 * never does this, so 403 costs nothing and a broken one gets told.
 *
 * Rejections are 4xx by design, because the client is fire-and-forget with
 * retry: it retries transport failures and drops 4xx, so a malformed batch
 * fails once rather than looping.
 */
export const ingestAnalyticsEventsAnalyticsEventsPost = <ThrowOnError extends boolean = false>(options: Options<IngestAnalyticsEventsAnalyticsEventsPostData, ThrowOnError>): RequestResult<IngestAnalyticsEventsAnalyticsEventsPostResponses, IngestAnalyticsEventsAnalyticsEventsPostErrors, ThrowOnError> => (options.client ?? client).post<IngestAnalyticsEventsAnalyticsEventsPostResponses, IngestAnalyticsEventsAnalyticsEventsPostErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/analytics/events',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

